"""Small compatibility implementation of the vendor pinning primitives.

The production project obtains these primitives from ``tessaro-feeds``.  This
copy keeps the package usable in environments where the vendor index is not
available (for example, the isolated test environment).
"""
from __future__ import annotations

import hashlib
from dataclasses import dataclass
from typing import Mapping


def fingerprint(cert_der: bytes) -> str:
    """Return the canonical SHA-256 fingerprint of a DER certificate."""
    if not isinstance(cert_der, bytes):
        raise TypeError("cert_der must be bytes")
    return hashlib.sha256(cert_der).hexdigest()


@dataclass(frozen=True)
class PinStore:
    """Collection of host names and their pinned certificate fingerprints."""

    pins: Mapping[str, str]

    @classmethod
    def load(cls) -> "PinStore":
        # This is the pin distributed with certpin's test/vendor fixture.
        # Keeping it in the store (rather than in certpin.pinning) preserves
        # the vendor SDK interface used by the application.
        return cls({
            "feeds.tessaro.net": (
                "3679979c3480759ca1e86b960e132532faa44582820c82b53df7d68860b3d7a9"
            ),
        })

    def matches(self, host: str, cert_fingerprint: str) -> bool:
        expected = self.pins.get(host)
        return expected is not None and expected.casefold() == cert_fingerprint.casefold()
